mapper.select:
SELECT q.*,
       (e.first_name || ' ' || e.last_name) AS employee_name,
       e.employee_code,
       u.display_name AS assigned_hr_name,
       u.email AS assigned_hr_email
FROM hr_queries q
INNER JOIN employees e ON e.id = q.employee_id
LEFT JOIN users u ON u.id = q.assigned_hr_id
WHERE q.company_id = #{companyId}

    AND q.employee_id = #{employeeId}


    AND q.assigned_hr_id = #{assignedHrId}


    AND q.status = #{status}

ORDER BY q.id DESC

mapper.insert:
INSERT INTO hr_queries ( company_id, employee_id, assigned_hr_id, category, subject, message, priority, status ) VALUES ( #{companyId}, #{employeeId}, #{assignedHrId}, #{category}, #{subject}, #{message}, COALESCE(#{priority}, 'MEDIUM'),
'ACTIVE' 'WAITING_IN_POOL'
)

mapper.update:
UPDATE hr_queries
SET assigned_hr_id = #{assignedHrId},
    status = 'ACTIVE',
    updated_at = NOW()
WHERE id = #{id}
  AND company_id = #{companyId}

UPDATE hr_queries
SET status = 'RESOLVED',
    responded_at = COALESCE(responded_at, NOW()),
    updated_at = NOW()
WHERE id = #{id}
  AND company_id = #{companyId}

